/// <summary>
/// Form event handler for <c>PriceDiscAdmTable</c> datasource of <c>PriceDiscAdmTable</c> form
/// </summary>
class GUPPriceDiscAdmTableDSFormEventHandler
{
}

Method.Source:
/// <summary>
/// If run for Unified pricing service - only Sales price journal names are available
/// </summary>
/// <param name="_sender">Data source</param>
/// <param name="_e">Parameter</param>
[FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable), FormDataSourceEventType::Initialized)]
public static void PriceDiscAdmTable_OnInitialized(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (_sender.formRun().args().menuItemName() == menuItemDisplayStr(GUPPriceDiscAdmTable_Sales))
        {
            _sender.object(fieldNum(PriceDiscAdmTable, DefaultRelation)).allowEdit(false);
            _sender.queryBuildDataSource().addRange(fieldNum(PriceDiscAdmTable, DefaultRelation)).value(queryValue(PriceType::PriceSales));
            _sender.formRun().design().controlName(formControlStr(PriceDiscAdmTable, PriceDiscAdmTable_PriceDiscPriceAttributeEnable)).visible(true);
    
            if (_sender.formRun().args() && _sender.formRun().args().dataset() == tableNum(GUPPriceComponentCodePriceAttributeGroupCombination))
            {
                GUPPriceComponentCodePriceAttributeGroupCombination groupCombination = _sender.formRun().args().record();
                _sender.queryBuildDataSource().addRange(fieldNum(PriceDiscAdmTable, PriceComponentCombination)).value(queryValue(groupCombination.RecId));
            }
        }
    }
}

    [FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable), FormDataSourceEventType::Activated)]
    public static void PriceDiscAdmTable_OnActivated(FormDataSource _sender, FormDataSourceEventArgs _e)
    {
        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            if (_sender.formRun().args().menuItemName() == menuItemDisplayStr(GUPPriceDiscAdmTable_Sales))
            {
                PriceDiscAdmTable priceDiscAdmTable = _sender.cursor();
                boolean priceAttributeEnabled = priceDiscAdmTable.priceDiscPriceAttributeEnable();

                _sender.object(fieldNum(PriceDiscAdmTable, PriceComponentCombination)).allowEdit(priceAttributeEnabled);
                _sender.object(fieldNum(PriceDiscAdmTable, PriceApplyAdjustment)).allowEdit(priceAttributeEnabled);
            }
            else
            {
                _sender.object(fieldNum(PriceDiscAdmTable, PriceComponentCombination)).allowEdit(false);
                _sender.object(fieldNum(PriceDiscAdmTable, PriceApplyAdjustment)).allowEdit(false);
            }
        }
    }
